function validate([nums, key]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 1000) return 'nums needs 2 to 1000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'Each value in nums is an integer from 1 to 1000.';
  if (!nums.includes(key)) return 'key must occur in nums.';
  const counts = new Map();
  for (let i = 0; i + 1 < nums.length; i++) if (nums[i] === key) counts.set(nums[i + 1], (counts.get(nums[i + 1]) ?? 0) + 1);
  const values = [...counts.values()];
  if (!values.length) return 'key must be followed by at least one number.';
  const top = Math.max(...values);
  if (values.filter(c => c === top).length !== 1) return 'Exactly one number may have the highest count.';
  return null;
}

