function mostFrequent(nums, key) {
  const counts = new Map();
  let best = -1;
  let bestCount = 0;

  for (let i = 0; i + 1 < nums.length; i++) {
    if (nums[i] !== key) {
      continue;
    }
    const target = nums[i + 1];
    const count = (counts.get(target) ?? 0) + 1;
    counts.set(target, count);
    if (count > bestCount) {
      bestCount = count;
      best = target;
    }
  }

  return best;
}

