function generate(rand, size) {
  const small = size === 'small';
  const unique = (nums, key) => {
    const counts = new Map();
    for (let i = 0; i + 1 < nums.length; i++) if (nums[i] === key) counts.set(nums[i + 1], (counts.get(nums[i + 1]) ?? 0) + 1);
    const values = [...counts.values()];
    if (!values.length) return false;
    const top = Math.max(...values);
    return values.filter(c => c === top).length === 1;
  };
  // The answer must be unique, so retry until one target strictly leads.
  for (;;) {
    const n = small ? 2 + Math.floor(rand() * 9) : 900 + Math.floor(rand() * 101);
    const range = small ? 1 + Math.floor(rand() * 5) : (rand() < 0.5 ? 20 : 1000);
    const key = 1 + Math.floor(rand() * range);
    const favorite = 1 + Math.floor(rand() * range);
    const keyRate = 0.1 + rand() * 0.3;
    const nums = [];
    for (let i = 0; i < n; i++) {
      const roll = rand();
      if (roll < keyRate) nums.push(key);
      else if (roll < keyRate + 0.2) nums.push(favorite);
      else nums.push(1 + Math.floor(rand() * range));
    }
    if (unique(nums, key)) return [nums, key];
  }
}
